def find_rectangular_shapes(grid):
    """Find potential rectangles based on non-background colors"""
    shapes = {}

    # Group by color
    for color in [5, 8, 9]:
        cells = []
        for r in range(10):
            for c in range(24):
                if grid[r][c] == color:
                    cells.append((r, c))

        if not cells:
            continue

        # Find bounding box
        min_r, max_r = min(r for r,c in cells), max(r for r,c in cells)
        min_c, max_c = min(c for r,c in cells), max(c for r,c in cells)

        # Check how many cells would be needed for full rectangle
        expected = (max_r - min_r + 1) * (max_c - min_c + 1)
        actual = len(cells)

        if expected > actual:  # Incomplete rectangle
            shapes.setdefault(color, []).append({
                'bbox': (min_r, min_c, max_r, max_c),
                'cells': cells.copy(),
                'expected': expected,
                'actual': actual
            })

    return shapes

