from collections import deque

def get_connected_components(grid):
    """Find connected components of non-background cells"""
    visited = [[False]*24 for _ in range(10)]
    components = []

    directions = [(-1,0), (1,0), (0,-1), (0,1)]  # Up, Down, Left, Right

    for r in range(10):
        for c in range(24):
            if grid[r][c] != 4 and not visited[r][c]:
                component = {}
                q = deque([(r, c)])
                visited[r][c] = True

                while q:
                    cr, cc = q.popleft()
                    comp_color = grid[cr][cc]

                    if comp_color not in component:
                        component[comp_color] = []
                    component[comp_color].append((cr, cc))

                    for dr, dc in directions:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < 10 and 0 <= nc < 24:
                            if grid[nr][nc] == comp_color and not visited[nr][nc]:
                                visited[nr][nc] = True
                                q.append((nr, nc))

                components.append(component)

    return components

