def complete_components(grid):
    """Complete each connected component into its bounding box"""
    result = [[4]*24 for _ in range(10)]

    # Find all connected components  
    visited = [[False]*24 for _ in range(10)]
    directions = [(-1,0), (1,0), (0,-1), (0,1)]

    for r in range(10):
        for c in range(24):
            if grid[r][c] != 4 and not visited[r][c]:
                # BFS to find component
                q = [(r, c)]
                component = {(r,c)}
                visited[r][c] = True

                while q:
                    cr, cc = q.pop(0)
                    comp_color = grid[cr][cc]

                    for dr, dc in directions:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < 10 and 0 <= nc < 24:
                            if grid[nr][nc] == comp_color and not visited[nr][nc]:
                                visited[nr][nc] = True
                                component.add((nr, nc))
                                q.append((nr, nc))

                # Fill bounding box
                if len(component) > 1:
                    min_r = min(cell[0] for cell in component)
                    max_r = max(cell[0] for cell in component)
                    min_c = min(cell[1] for cell in component)
                    max_c = max(cell[1] for cell in component)

                    # Fill bbox with component's color
                    for rr in range(min_r, max_r+1):
                        for cc in range(min_c, max_c+1):
                            result[rr][cc] = comp_color

                else:
