def create_compact_rectangles(grid):
    """Create minimal bounding boxes for each color cluster"""
    result = [[4]*24 for _ in range(10)]

    # Group by color
    from collections import defaultdict
    color_groups = defaultdict(list)

    for r in range(10):
        for c in range(24):
            if grid[r][c] != 4:
                color_groups[grid[r][c]].append((r, c))

    # For each color, fill its overall bounding box
    for color, cells in color_groups.items():
        min_r = min(c[0] for c in cells)
        max_r = max(c[0] for c in cells)
        min_c = min(c[1] for c in cells)
        max_c = max(c[1] for c in cells)

        for rr in range(min_r, max_r + 1):
            for cc in range(min_c, max_c + 1):
                result[rr][cc] = color

